impl SseEncode for crate::api::activity::ActivityIntent {
    // Codec=Sse (Serialization based), see doc to use other codecs
    fn sse_encode(self, serializer: &mut flutter_rust_bridge::for_generated::SseSerializer) {
        match self {
            crate::api::activity::ActivityIntent::SetConnected { connected } => {
                <i32>::sse_encode(0, serializer);
                <bool>::sse_encode(connected, serializer);
            }
            crate::api::activity::ActivityIntent::Watch { chat, token } => {
                <i32>::sse_encode(1, serializer);
                <crate::api::overview::ChatRefView>::sse_encode(chat, serializer);
                <u64>::sse_encode(token, serializer);
            }
            crate::api::activity::ActivityIntent::Release { token } => {
                <i32>::sse_encode(2, serializer);
                <u64>::sse_encode(token, serializer);
            }
            crate::api::activity::ActivityIntent::Load { chat } => {
                <i32>::sse_encode(3, serializer);
                <crate::api::overview::ChatRefView>::sse_encode(chat, serializer);
            }
            crate::api::activity::ActivityIntent::SetHookPaused {
                chat,
                hook_key,
                paused,
            } => {
                <i32>::sse_encode(4, serializer);
                <crate::api::overview::ChatRefView>::sse_encode(chat, serializer);
                <String>::sse_encode(hook_key, serializer);
                <bool>::sse_encode(paused, serializer);
            }
            crate::api::activity::ActivityIntent::RunPr {
                chat,
                action,
                repo_id,
                identity,
                confirm_unresolved_comments,
            } => {
                <i32>::sse_encode(5, serializer);
                <crate::api::overview::ChatRefView>::sse_encode(chat, serializer);
                <crate::api::activity::PrActionKind>::sse_encode(action, serializer);
                <Option<String>>::sse_encode(repo_id, serializer);
                <Option<crate::api::activity::PrIdentityView>>::sse_encode(identity, serializer);
                <bool>::sse_encode(confirm_unresolved_comments, serializer);
            }
            crate::api::activity::ActivityIntent::WatchDiff { target, token } => {
                <i32>::sse_encode(6, serializer);
                <crate::api::activity::DiffTargetView>::sse_encode(target, serializer);
                <u64>::sse_encode(token, serializer);
            }
            crate::api::activity::ActivityIntent::ReleaseDiff { token } => {
                <i32>::sse_encode(7, serializer);
                <u64>::sse_encode(token, serializer);
            }
            crate::api::activity::ActivityIntent::RefreshDiff { target } => {
                <i32>::sse_encode(8, serializer);
                <crate::api::activity::DiffTargetView>::sse_encode(target, serializer);
            }
            crate::api::activity::ActivityIntent::Close => {
                <i32>::sse_encode(9, serializer);
            }
            _ => {
                unimplemented!("");
            }
        }
    }
}

